/* 학습 해설
 * 커널 Crypto API · 알고리즘과 구현 선택
 * 여러 서브시스템이 암호·해시·인증 기능을 공통 API로 사용하면서 구현을 선택할 수 있어야 합니다.
 * 알고리즘 이름과 타입으로 구현을 찾으며 소프트웨어·가속 구현이 등록될 수 있습니다. 암호화·해시·인증은 다른 목적이며 비동기 요청은 완료 규칙을 따릅니다.
 * 알고리즘의 모드·키·nonce 규약을 확인합니다. 해시가 있다는 사실만으로 비밀성이나 변조 방지가 자동 보장되는 것은 아닙니다.
 */
void *crypto_alloc_tfm_node(const char *alg_name,
		       const struct crypto_type *frontend, u32 type, u32 mask,
		       int node)
{
	void *tfm;
	int err;

	for (;;) {
		struct crypto_alg *alg;

		alg = crypto_find_alg(alg_name, frontend, type, mask);
		if (IS_ERR(alg)) {
			err = PTR_ERR(alg);
			goto err;
		}

		tfm = crypto_create_tfm_node(alg, frontend, node);
		if (!IS_ERR(tfm))
			return tfm;

		crypto_mod_put(alg);
		err = PTR_ERR(tfm);

err:
		if (err != -EAGAIN)
			break;

