/* 학습 해설
 * 난수·CRNG · 예측 불가능한 값
 * 보안 키와 nonce에 단순 반복 패턴이나 시각 기반 숫자를 사용하면 예측 위험이 있습니다.
 * 커널 난수 시스템은 엔트로피 수집과 암호학적 생성기를 사용합니다. 초기화 상태와 API 규약이 중요하며 일반 PRNG·해시 테이블용 랜덤화와 보안 난수를 혼동하지 않습니다.
 * 사용자 공간에서는 getrandom API의 초기화·오류·부분 반환을 처리합니다. 커널에서 get_random_bytes를 쓰고 무작위 값의 유일성이 자동 보장된다고 생각하지 않습니다.
 */
void get_random_bytes(void *buf, size_t len)
{
	warn_unseeded_randomness();
	_get_random_bytes(buf, len);
}
EXPORT_SYMBOL(get_random_bytes);

static ssize_t get_random_bytes_user(struct iov_iter *iter)
{
	u32 chacha_state[CHACHA_STATE_WORDS];
	u8 block[CHACHA_BLOCK_SIZE];
	size_t ret = 0, copied;

	if (unlikely(!iov_iter_count(iter)))
		return 0;

	/*
	 * Immediately overwrite the ChaCha key at index 4 with random
	 * bytes, in case userspace causes copy_to_iter() below to sleep
	 * forever, so that we still retain forward secrecy in that case.
	 */
	crng_make_state(chacha_state, (u8 *)&chacha_state[4], CHACHA_KEY_SIZE);
	/*
	 * However, if we're doing a read of len <= 32, we don't need to
	 * use chacha_state after, so we can simply return those bytes to
	 * the user directly.
	 */

