/* 학습 해설
 * MMIO · 레지스터와 접근 순서
 * 장치 레지스터는 일반 RAM처럼 캐시하거나 컴파일러가 임의로 접근을 바꾸면 안 됩니다.
 * I/O 매핑과 readl·writel 같은 접근 API가 아키텍처별 장치 접근 의미를 제공합니다. 엔디언·순서·posted write 규칙은 장치와 API에 달려 있습니다. volatile 하나만으로 모든 규약을 대신할 수 없습니다.
 * 자원을 ioremap 계열로 매핑하고 문서화된 접근 함수를 사용합니다. 레지스터 읽기가 상태를 지우는 등 부작용이 있을 수 있어 실제 장치에서 임의 실험하지 않습니다.
 */
static inline u32 readl(const volatile void __iomem *addr)
{
	u32 val;

	log_read_mmio(32, addr, _THIS_IP_, _RET_IP_);
	__io_br();
	val = __le32_to_cpu((__le32 __force)__raw_readl(addr));
	__io_ar(val);
	log_post_read_mmio(val, 32, addr, _THIS_IP_, _RET_IP_);
	return val;
}
#endif

#ifdef CONFIG_64BIT
#ifndef readq
#define readq readq
static inline u64 readq(const volatile void __iomem *addr)
{
	u64 val;

	log_read_mmio(64, addr, _THIS_IP_, _RET_IP_);
	__io_br();
	val = __le64_to_cpu((__le64 __force)__raw_readq(addr));
	__io_ar(val);
	log_post_read_mmio(val, 64, addr, _THIS_IP_, _RET_IP_);
	return val;

