/* 학습 해설
 * DMA · 장치 접근과 버퍼 소유권
 * CPU 복사 없이 장치가 메모리 데이터를 직접 읽거나 쓸 수 있어야 합니다.
 * DMA API는 장치가 접근할 주소와 캐시 일관성·방향·동기화를 처리합니다. streaming과 coherent 매핑은 규약이 다릅니다. coherent 메모리도 CPU·장치 간 모든 논리적 순서와 수명까지 자동 해결하지는 않습니다.
 * DMA_TO_DEVICE·FROM_DEVICE·BIDIRECTIONAL을 실제 방향에 맞춰 선택하고 mapping_error·unmap·sync 규칙을 따릅니다. CPU 포인터를 장치 주소로 무조건 전달하지 않습니다.
 */
static inline dma_addr_t dma_direct_map_page(struct device *dev,
		struct page *page, unsigned long offset, size_t size,
		enum dma_data_direction dir, unsigned long attrs)
{
	phys_addr_t phys = page_to_phys(page) + offset;
	dma_addr_t dma_addr = phys_to_dma(dev, phys);

	if (is_swiotlb_force_bounce(dev)) {
		if (is_pci_p2pdma_page(page))
			return DMA_MAPPING_ERROR;
		return swiotlb_map(dev, phys, size, dir, attrs);
	}

	if (unlikely(!dma_capable(dev, dma_addr, size, true)) ||
	    dma_kmalloc_needs_bounce(dev, size, dir)) {
		if (is_pci_p2pdma_page(page))
			return DMA_MAPPING_ERROR;
		if (is_swiotlb_active(dev))
			return swiotlb_map(dev, phys, size, dir, attrs);

		dev_WARN_ONCE(dev, 1,
			     "DMA addr %pad+%zu overflow (mask %llx, bus limit %llx).\n",
			     &dma_addr, size, *dev->dma_mask, dev->bus_dma_limit);
		return DMA_MAPPING_ERROR;
	}

