/* 학습 해설
 * IOMMU · 장치 주소 변환과 격리
 * 장치가 사용하는 주소를 물리 메모리에 연결하고 접근 범위를 제한할 수 있어야 합니다.
 * IOMMU는 장치 주소 IOVA를 물리 페이지에 매핑하는 도메인과 권한을 관리합니다. CPU MMU와 다른 접근 주체를 처리합니다. 하드웨어·구성·장치 그룹에 따라 격리 단위가 달라집니다.
 * DMA API와 IOMMU 직접 API의 사용자·드라이버 역할을 구분합니다. 장치 할당에서는 IOMMU group과 실제 격리 능력을 확인합니다.
 */
int iommu_map(struct iommu_domain *domain, unsigned long iova,
	      phys_addr_t paddr, size_t size, int prot, gfp_t gfp)
{
	const struct iommu_domain_ops *ops = domain->ops;
	int ret;

	might_sleep_if(gfpflags_allow_blocking(gfp));

	/* Discourage passing strange GFP flags */
	if (WARN_ON_ONCE(gfp & (__GFP_COMP | __GFP_DMA | __GFP_DMA32 |
				__GFP_HIGHMEM)))
		return -EINVAL;

	ret = __iommu_map(domain, iova, paddr, size, prot, gfp);
	if (ret == 0 && ops->iotlb_sync_map) {
		ret = ops->iotlb_sync_map(domain, iova, size);
		if (ret)
			goto out_err;
	}

	return ret;

out_err:
	/* undo mappings already done */
	iommu_unmap(domain, iova, size);

