/* 학습 해설
 * USB·URB · 비동기 전송 요청
 * USB endpoint 전송을 비동기적으로 제출하고 완료·취소를 관리해야 합니다.
 * URB에 endpoint·버퍼·길이·완료 콜백 등을 담아 호스트 컨트롤러에 제출합니다. 완료 status와 실제 전송 길이가 결과를 나타냅니다. 취소·분리·버퍼 수명의 경쟁을 관리해야 합니다.
 * usb_submit_urb 반환은 요청 제출 여부이며 성공 전송 완료 자체가 아닙니다. 완료 콜백·usb_kill_urb와 객체 수명을 짝지어 설계합니다.
 */
int usb_submit_urb(struct urb *urb, gfp_t mem_flags)
{
	int				xfertype, max;
	struct usb_device		*dev;
	struct usb_host_endpoint	*ep;
	int				is_out;
	unsigned int			allowed;

	if (!urb || !urb->complete)
		return -EINVAL;
	if (urb->hcpriv) {
		WARN_ONCE(1, "URB %pK submitted while active\n", urb);
		return -EBUSY;
	}

	dev = urb->dev;
	if ((!dev) || (dev->state < USB_STATE_UNAUTHENTICATED))
		return -ENODEV;

	/* For now, get the endpoint from the pipe.  Eventually drivers
	 * will be required to set urb->ep directly and we will eliminate
	 * urb->pipe.
	 */
	ep = usb_pipe_endpoint(dev, urb->pipe);
	if (!ep)
		return -ENOENT;

