/* 학습 해설
 * Virtio · Descriptor Ring과 통지
 * 가상 장치와 게스트가 효율적으로 데이터 버퍼와 완료 정보를 교환해야 합니다.
 * virtqueue descriptor가 버퍼 주소·길이·연결을 표현하고 available·used 정보로 제출과 완료를 교환합니다. split·packed ring 방식과 기능 협상이 있으며 데이터 공개 순서·통지·버퍼 수명을 지켜야 합니다.
 * virtqueue에 넣은 버퍼는 완료 회수 전에 해제하지 않습니다. kick과 완료 통지를 구분하고 불필요한 통지 억제의 조건을 확인합니다.
 */
int virtqueue_add_sgs(struct virtqueue *_vq,
		      struct scatterlist *sgs[],
		      unsigned int out_sgs,
		      unsigned int in_sgs,
		      void *data,
		      gfp_t gfp)
{
	unsigned int i, total_sg = 0;

	/* Count them first. */
	for (i = 0; i < out_sgs + in_sgs; i++) {
		struct scatterlist *sg;

		for (sg = sgs[i]; sg; sg = sg_next(sg))
			total_sg++;
	}
	return virtqueue_add(_vq, sgs, total_sg, out_sgs, in_sgs,
			     data, NULL, gfp);
}
EXPORT_SYMBOL_GPL(virtqueue_add_sgs);

