 * Ftrace·Tracepoint · 실행 사건 관찰
 * 함수 호출과 주요 커널 사건을 구조화해 관찰해야 합니다.
 * trace buffer에 사건을 저장하고 tracer·event 설정으로 관측 범위를 선택합니다. tracepoint는 미리 마련된 사건 지점이며 함수 추적과 같지는 않습니다. CPU별 버퍼·타임스탬프·손실을 고려해야 합니다.
 * tracefs의 available_events를 조회하고 필요한 사건만 선택합니다. 관찰 비용과 권한이 있으며 실제 활성화·기록은 시스템 동작에 영향을 줄 수 있습니다.
 */
static int tracing_open(struct inode *inode, struct file *file)
{
	struct trace_array *tr = inode->i_private;
	struct trace_iterator *iter;
	int ret;

	ret = tracing_check_open_get_tr(tr);
	if (ret)
		return ret;

	/* If this file was open for write, then erase contents */
	if ((file->f_mode & FMODE_WRITE) && (file->f_flags & O_TRUNC)) {
		int cpu = tracing_get_cpu(inode);
		struct array_buffer *trace_buf = &tr->array_buffer;

#ifdef CONFIG_TRACER_MAX_TRACE
		if (tr->current_trace->print_max)
			trace_buf = &tr->max_buffer;
#endif

		if (cpu == RING_BUFFER_ALL_CPUS)
			tracing_reset_online_cpus(trace_buf);
		else
			tracing_reset_cpu(trace_buf, cpu);
	}

