/* 학습 해설
 * Kprobe · 동적 실행 지점 관찰
 * 미리 정의된 tracepoint가 없는 함수도 지정 지점에서 관찰하고 싶을 수 있습니다.
 * kprobe는 지원되는 실행 지점에 probe를 등록해 handler를 호출합니다. 아키텍처별 명령 처리와 금지 영역·재진입 규칙이 있으며 어떤 함수에나 임의 동작을 넣는 무제한 인터페이스가 아닙니다.
 * 핸들러의 수면·재진입·메모리 접근 제약을 확인합니다. 커널 버전별 함수명과 인자 ABI가 바뀔 수 있어 영구 안정 인터페이스처럼 다루지 않습니다.
 */
int register_kprobe(struct kprobe *p)
{
	int ret;
	struct kprobe *old_p;
	struct module *probed_mod;
	kprobe_opcode_t *addr;
	bool on_func_entry;

	/* Adjust probe address from symbol */
	addr = _kprobe_addr(p->addr, p->symbol_name, p->offset, &on_func_entry);
	if (IS_ERR(addr))
		return PTR_ERR(addr);
	p->addr = addr;

	ret = warn_kprobe_rereg(p);
	if (ret)
		return ret;

	/* User can pass only KPROBE_FLAG_DISABLED to register_kprobe */
	p->flags &= KPROBE_FLAG_DISABLED;
	p->nmissed = 0;
	INIT_LIST_HEAD(&p->list);

	ret = check_kprobe_address_safe(p, &probed_mod);
	if (ret)
		return ret;

