/* 학습 해설
 * KASAN·Sanitizer · 잘못된 메모리 접근 탐지
 * 경계 밖 접근과 해제 후 사용을 더 빠르게 찾아야 합니다.
 * KASAN은 모드에 따라 shadow·tag 정보를 이용해 메모리 접근의 유효성을 검사합니다. KCSAN·UBSAN은 다른 종류의 문제를 다룹니다. 빌드 설정·아키텍처·오버헤드와 탐지 한계가 있습니다.
 * 보고서의 접근 위치·할당·해제 스택을 연결합니다. KASAN이 없는 정상 실행 결과만으로 메모리 안전성을 증명하지 않습니다.
 */
bool kasan_report(const void *addr, size_t size, bool is_write,
			unsigned long ip)
{
	bool ret = true;
	unsigned long ua_flags = user_access_save();
	unsigned long irq_flags;
	struct kasan_report_info info;

	if (unlikely(report_suppressed_sw()) || unlikely(!report_enabled())) {
		ret = false;
		goto out;
	}

	start_report(&irq_flags, true);

	__memset(&info, 0, sizeof(info));
	info.type = KASAN_REPORT_ACCESS;
	info.access_addr = addr;
	info.access_size = size;
	info.is_write = is_write;
	info.ip = ip;

	complete_report_info(&info);

	print_report(&info);

