/* 학습 해설
 * Initcall·PID 1 · 초기화 순서와 사용자 공간
 * 커널 초기화와 장치 준비를 마친 뒤 최초 사용자 공간 프로그램을 실행해야 합니다.
 * initcall 레벨로 등록된 초기화 함수를 순서에 따라 호출합니다. 이후 init 프로그램 실행 경로가 사용자 공간을 시작합니다. initcall 순서만으로 모든 장치 의존 관계가 자동 해결되는 것은 아닙니다.
 * start_kernel·do_initcalls·kernel_init을 연결하고 initramfs와 최종 rootfs의 역할을 구분합니다. PID 1은 자식 수거 등 특별한 운영 책임을 갖습니다.
 */
static void __init do_initcalls(void)
{
	int level;
	size_t len = saved_command_line_len + 1;
	char *command_line;

	command_line = kzalloc(len, GFP_KERNEL);
	if (!command_line)
		panic("%s: Failed to allocate %zu bytes\n", __func__, len);

	for (level = 0; level < ARRAY_SIZE(initcall_levels) - 1; level++) {
		/* Parser modifies command_line, restore it each time */
		strcpy(command_line, saved_command_line);
		do_initcall_level(level, command_line);
	}

	kfree(command_line);
}

