/* 학습 해설
 * Hlist·container_of · 객체에 노드를 넣기
 * 해시 버킷마다 큰 리스트 헤드를 두지 않고 객체 자체에 연결 노드를 넣고 싶습니다.
 * hlist는 next와 이전 연결의 주소인 pprev를 사용해 헤드를 작게 유지합니다. container_of는 멤버 주소와 오프셋으로 포함 객체를 찾습니다. 멤버 주소가 유효한 해당 객체에서 나온 경우에만 의미가 있습니다.
 * 노드 삽입·삭제와 객체 수명을 함께 관리합니다. 구조체를 복사해 노드 연결을 그대로 재사용하면 연결 관계가 깨질 수 있습니다.
 */
static inline void hlist_add_head(struct hlist_node *n, struct hlist_head *h)
{
	struct hlist_node *first = h->first;
	WRITE_ONCE(n->next, first);
	if (first)
		WRITE_ONCE(first->pprev, &n->next);
	WRITE_ONCE(h->first, n);
	WRITE_ONCE(n->pprev, &h->first);
}

/**
 * hlist_add_before - add a new entry before the one specified
 * @n: new entry to be added
 * @next: hlist node to add it before, which must be non-NULL
 */
static inline void hlist_add_before(struct hlist_node *n,
				    struct hlist_node *next)
{
	WRITE_ONCE(n->pprev, next->pprev);
	WRITE_ONCE(n->next, next);
	WRITE_ONCE(next->pprev, &n->next);
	WRITE_ONCE(*(n->pprev), n);
}

/**
 * hlist_add_behind - add a new entry after the one specified
 * @n: new entry to be added
 * @prev: hlist node to add it after, which must be non-NULL
 */

