/* 학습 해설
 * CPU Hotplug · 온라인 상태와 콜백
 * CPU를 온라인·오프라인으로 전환할 때 각 서브시스템의 지역 상태도 정리해야 합니다.
 * 상태 단계와 콜백으로 CPU 준비·정리를 진행합니다. 태스크 이동·타이머·작업 큐·인터럽트 등의 의존이 있으며 온라인 CPU 집합이 고정이라는 가정을 피해야 합니다.
 * present·possible·online CPU 집합을 구분합니다. 학습에서는 sysfs 상태를 조회하며 실제 CPU 끄기는 요구하지 않습니다.
 */
static int cpu_up(unsigned int cpu, enum cpuhp_state target)
{
	int err = 0;

	if (!cpu_possible(cpu)) {
		pr_err("can't online cpu %d because it is not configured as may-hotadd at boot time\n",
		       cpu);
		return -EINVAL;
	}

	err = try_online_node(cpu_to_node(cpu));
	if (err)
		return err;

	cpu_maps_update_begin();

	if (cpu_hotplug_disabled) {
		err = -EBUSY;
		goto out;
	}
	if (!cpu_bootable(cpu)) {
		err = -EPERM;
		goto out;
	}

	err = _cpu_up(cpu, 0, target);

