/* 학습 해설
 * Semaphore · 가용 자원 개수
 * 동시에 사용할 수 있는 자원의 수를 카운트로 제한해야 합니다.
 * 세마포어의 값을 감소해 자원을 얻고 증가해 반환합니다. 값이 부족하면 대기할 수 있습니다. SysV 세마포어 배열의 여러 연산은 하나의 요청에서 조건을 함께 처리하며 mutex의 소유권 규칙과 다릅니다.
 * 자원 반납·오류·종료 경로와 SEM_UNDO 의미를 확인합니다. mutex와 세마포어를 이름만으로 서로 대체하지 않습니다.
 */
static long do_semtimedop(int semid, struct sembuf __user *tsops,
		unsigned nsops, const struct timespec64 *timeout)
{
	struct sembuf fast_sops[SEMOPM_FAST];
	struct sembuf *sops = fast_sops;
	struct ipc_namespace *ns;
	int ret;

	ns = current->nsproxy->ipc_ns;
	if (nsops > ns->sc_semopm)
		return -E2BIG;
	if (nsops < 1)
		return -EINVAL;

	if (nsops > SEMOPM_FAST) {
		sops = kvmalloc_array(nsops, sizeof(*sops), GFP_KERNEL);
		if (sops == NULL)
			return -ENOMEM;
	}

	if (copy_from_user(sops, tsops, nsops * sizeof(*tsops))) {
		ret =  -EFAULT;
		goto out_free;
	}

	ret = __do_semtimedop(semid, sops, nsops, timeout, ns);

