/* 학습 해설
 * Rwsem · 독자 공유와 writer 배제
 * 여러 독자가 함께 읽되 쓰기 중에는 일관성을 지켜야 합니다.
 * 읽기 잠금은 여러 독자를 허용하고 쓰기 잠금은 배타적으로 접근합니다. 잠들 수 있는 잠금이며 reader·writer 대기와 공정성·경합 비용을 고려합니다.
 * down_read·up_read와 down_write·up_write를 맞춥니다. 읽기 잠금을 가진 채 무조건 쓰기 잠금으로 올리면 데드락 위험이 있습니다.
 */
void __sched down_read(struct rw_semaphore *sem)
{
	might_sleep();
	rwsem_acquire_read(&sem->dep_map, 0, 0, _RET_IP_);

	LOCK_CONTENDED(sem, __down_read_trylock, __down_read);
}
EXPORT_SYMBOL(down_read);

int __sched down_read_interruptible(struct rw_semaphore *sem)
{
	might_sleep();
	rwsem_acquire_read(&sem->dep_map, 0, 0, _RET_IP_);

	if (LOCK_CONTENDED_RETURN(sem, __down_read_trylock, __down_read_interruptible)) {
		rwsem_release(&sem->dep_map, _RET_IP_);
		return -EINTR;
	}

	return 0;
}
EXPORT_SYMBOL(down_read_interruptible);

int __sched down_read_killable(struct rw_semaphore *sem)
{
	might_sleep();

