/* 학습 해설
 * Device Mapper·RAID · 블록 장치 조합
 * 여러 장치·변환을 하나의 논리 블록 장치처럼 사용하고 싶습니다.
 * device mapper는 논리 구간을 target에 연결해 요청을 변환·분배합니다. RAID의 striping·mirroring·parity는 각각 성능·복제·복구 목표가 다릅니다. RAID는 파일 버전 백업을 대신하지 않습니다.
 * lsblk로 장치 계층을 조회하고 dm-crypt·LVM·RAID의 역할을 구분합니다. 구성 변경 없이 소스의 target 매핑과 완료를 읽습니다.
 */
static void dm_submit_bio(struct bio *bio)
{
	struct mapped_device *md = bio->bi_bdev->bd_disk->private_data;
	int srcu_idx;
	struct dm_table *map;

	map = dm_get_live_table(md, &srcu_idx);
	if (unlikely(!map)) {
		DMERR_LIMIT("%s: mapping table unavailable, erroring io",
			    dm_device_name(md));
		bio_io_error(bio);
		goto out;
	}

	/* If suspended, queue this IO for later */
	if (unlikely(test_bit(DMF_BLOCK_IO_FOR_SUSPEND, &md->flags))) {
		if (bio->bi_opf & REQ_NOWAIT)
			bio_wouldblock_error(bio);
		else if (bio->bi_opf & REQ_RAHEAD)
			bio_io_error(bio);
		else
			queue_io(md, bio);
		goto out;
	}

	dm_split_and_process_bio(md, map, bio);

