 * 네트워크 계층에서 정책에 따라 패킷을 보호·변환해야 합니다.
 * XFRM은 보안 정책과 상태를 조회해 IPsec 등의 변환 경로를 연결합니다. 정책과 실제 키·상태는 다른 객체이며 터널·전송 모드는 보호하는 패킷 구조가 다릅니다.
 * ip xfrm policy·state의 역할을 구분하고 암호·인증·키 협상은 각 규약에 맞춥니다. NAT가 암호화와 같다는 오해를 피합니다.
 */
struct dst_entry *xfrm_lookup(struct net *net, struct dst_entry *dst_orig,
			      const struct flowi *fl, const struct sock *sk,
			      int flags)
{
	return xfrm_lookup_with_ifid(net, dst_orig, fl, sk, flags, 0);
}
EXPORT_SYMBOL(xfrm_lookup);

/* Callers of xfrm_lookup_route() must ensure a call to dst_output().
 * Otherwise we may send out blackholed packets.
 */
struct dst_entry *xfrm_lookup_route(struct net *net, struct dst_entry *dst_orig,
				    const struct flowi *fl,
				    const struct sock *sk, int flags)
{
	struct dst_entry *dst = xfrm_lookup(net, dst_orig, fl, sk,
					    flags | XFRM_LOOKUP_QUEUE |
					    XFRM_LOOKUP_KEEP_DST_REF);

	if (PTR_ERR(dst) == -EREMOTE)
		return make_blackhole(net, dst_orig->ops->family, dst_orig);

	if (IS_ERR(dst))
		dst_release(dst_orig);

	return dst;

