/* 학습 해설
 * Bridge·VLAN · 링크 계층 전달
 * 여러 포트를 같은 링크처럼 연결하거나 논리 네트워크를 나눠야 합니다.
 * bridge는 MAC 학습과 forwarding database로 포트를 선택하며 VLAN은 태그와 포트 정책으로 링크 영역을 분리합니다. IP 라우팅의 목적지 접두사 탐색과는 계층이 다릅니다.
 * bridge fdb·vlan 조회와 ip route 조회를 구분합니다. VLAN 태그가 있다는 사실만으로 암호화나 모든 보안 격리가 제공되지는 않습니다.
 */
struct net_bridge_fdb_entry *br_fdb_find_rcu(struct net_bridge *br,
					     const unsigned char *addr,
					     __u16 vid)
{
	return fdb_find_rcu(&br->fdb_hash_tbl, addr, vid);
}

/* When a static FDB entry is added, the mac address from the entry is
 * added to the bridge private HW address list and all required ports
 * are then updated with the new information.
 * Called under RTNL.
 */
static void fdb_add_hw_addr(struct net_bridge *br, const unsigned char *addr)
{
	int err;
	struct net_bridge_port *p;

	ASSERT_RTNL();

	list_for_each_entry(p, &br->port_list, list) {
		if (!br_promisc_port(p)) {
			err = dev_uc_add(p->dev, addr);
			if (err)
				goto undo;
		}
	}

